+export const LEVELS = ["INFO", "WARN", "ERROR"] as const;
+
+export type LogLevel = (typeof LEVELS)[number];
+
+export interface LogEntry {
+  level: LogLevel;
+  message: string;
+}
+
+export interface LogSummary {
+  INFO: number;
+  WARN: number;
+  ERROR: number;
+  total: number;
+  ignored: number;
+}
+
+const logLinePattern = /^(?:\S+\s+)?(INFO|WARN|ERROR)\s+(.+)$/;
+
+export function parseLogLine(line: string): LogEntry | null {
+  const match = logLinePattern.exec(line.trim());
+  if (!match) {
+    return null;
+  }
+
+  return {
+    level: match[1] as LogLevel,
+    message: match[2],
+  };
+}
+
+export function summarizeLogs(lines: Iterable<string>): LogSummary {
+  const summary: LogSummary = {
+    INFO: 0,
+    WARN: 0,
+    ERROR: 0,
+    total: 0,
+    ignored: 0,
+  };
+
+  for (const line of lines) {
+    const entry = parseLogLine(line);
+    if (!entry) {
+      summary.ignored++;
+      continue;
+    }
+
+    summary[entry.level]++;
+    summary.total++;
+  }
+
+  return summary;
+}
+
