+#!/usr/bin/env node
+import { readFile } from "node:fs/promises";
+import { stdin } from "node:process";
+import { summarizeLogs } from "./parser";
+
+async function readInput(path: string | undefined): Promise<string> {
+  if (!path || path === "-") {
+    return new Promise((resolve, reject) => {
+      let input = "";
+      stdin.setEncoding("utf8");
+      stdin.on("data", (chunk) => {
+        input += chunk;
+      });
+      stdin.on("end", () => resolve(input));
+      stdin.on("error", reject);
+    });
+  }
+
+  return readFile(path, "utf8");
+}
+
+async function main(): Promise<void> {
+  const inputPath = process.argv[2];
+  const input = await readInput(inputPath);
+  console.log(JSON.stringify(summarizeLogs(input.split(/\r?\n/)), null, 2));
+}
+
+main().catch((error: unknown) => {
+  const message = error instanceof Error ? error.message : String(error);
+  console.error(`log-summary: ${message}`);
+  process.exitCode = 1;
+});
